<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free JSON Minifier Online','description'=>'Minify JSON by removing unnecessary whitespace.','url'=>'https://smarttoolz.in/tools/json-minifier/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>JSON Minifier</h1><p>Validate and minify JSON instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="12" placeholder="Paste JSON..."></textarea><button id="go" class="tool-btn">Minify JSON</button><textarea id="o" rows="12" readonly></textarea></div></section></main><script>go.onclick=()=>{try{o.value=JSON.stringify(JSON.parse(i.value))}catch(e){o.value='Invalid JSON.'}}</script><?php smarttoolz_tool_page_end(); ?>